  border: 1px solid rgba(239, 182, 97, 0.5);
  border-radius: 3px;
  background: linear-gradient(180deg, rgba(164, 105, 40, 0.4), rgba(95, 63, 28, 0.3));
  color: #f4d29a;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
}

.claim-btn:hover,
.claim-btn:focus-visible {
  border-color: var(--gold);
  background: linear-gradient(180deg, rgba(190, 126, 48, 0.55), rgba(110, 73, 31, 0.4));
}

.claim-btn kbd {
  margin-left: 5px;
  padding: 1px 4px;
  border: 1px solid rgba(244, 210, 154, 0.3);
  border-radius: 2px;
  font-family: var(--sans);
  font-size: 8px;
}

.fort-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-top: 13px;
}

.fort-btn {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
  padding: 8px 9px;
  border: 1px solid rgba(236, 219, 188, 0.12);
  border-radius: 3px;
  background: rgba(9, 14, 23, 0.55);
  color: var(--bone-dim);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.18s, background 0.18s, opacity 0.18s;
}

.fort-btn:hover:not(:disabled),
.fort-btn:focus-visible {
  border-color: rgba(239, 182, 97, 0.55);
  background: rgba(52, 38, 22, 0.42);
}

.fort-btn:disabled {
  opacity: 0.36;
  cursor: not-allowed;
}

.fort-top {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  width: 100%;
}

.fort-top b {
  overflow: hidden;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.fort-top em {
  margin-left: auto;
  color: var(--gold);
  font-size: 9px;
  font-style: normal;
  font-weight: 700;
}

.fort-btn small {
  overflow: hidden;
  color: var(--muted);
  font-size: 7.5px;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.res-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 50%;
}

.res-dot.wood {
  background: var(--wood);
  box-shadow: 0 0 5px rgba(176, 122, 71, 0.6);
}

.res-dot.stone {
  background: var(--stone);
  box-shadow: 0 0 5px rgba(154, 161, 160, 0.45);
}

.res-dot.scrap {
  background: var(--scrap);
  box-shadow: 0 0 5px rgba(127, 178, 165, 0.55);
}

.weapon-upgrade {
  display: flex;

  position: absolute;
  top: calc(126px + var(--safe-top));
  left: 50%;
  display: flex;
  width: min(400px, calc(100vw - 40px));
  flex-direction: column;
  gap: 7px;
  align-items: center;
  transform: translateX(-50%);
}

.toast {
  width: 100%;
  padding: 8px 12px 8px 11px;
  border: 1px solid rgba(236, 219, 188, 0.12);
  border-left: 2px solid var(--gold);
  border-radius: 2px 6px 6px 2px;
  background: rgba(8, 13, 21, 0.87);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.38);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  animation: toastIn 0.32s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
}

.toast.leaving {
  animation: toastOut 0.32s ease both;
}

.toast .t-title {
  color: var(--bone);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.toast .t-sub {
  margin-top: 2px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  line-height: 1.3;
}

.toast.alert {
  border-left-color: var(--red);
}

.toast.alert .t-title {
  color: #ef8a73;
}

.toast.good {
  border-left-color: var(--green);
}

.toast.good .t-title {
  color: #a6c8a8;
}

.toast.warn {
  border-left-color: var(--amber);
}

.toast.warn .t-title {
  color: var(--gold);
}

@keyframes toastIn {
  from { opacity: 0; transform: translateY(-8px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes toastOut {
  to { opacity: 0; transform: translateY(-5px); }
}

.center-banner {
  position: absolute;
  top: 30%;
  left: 50%;
  display: flex;
  width: min(720px, 90vw);
  flex-direction: column;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  text-align: center;
  transform: translate(-50%, 10px);
  transition: opacity 0.5s ease, transform 0.7s ease;
}

.center-banner.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.center-banner span {
  margin-bottom: 8px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.42em;
}

.center-banner strong {
  color: var(--bone);
  font-family: var(--serif);
  font-size: clamp(34px, 5vw, 64px);
  font-weight: 400;
  letter-spacing: 0.06em;
  line-height: 1;
  text-shadow: 0 2px 28px rgba(0, 0, 0, 0.85);
}

.center-banner small {
  margin-top: 11px;
  color: var(--bone-dim);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  letter-spacing: 0.03em;
  text-shadow: 0 2px 14px #000;
}

.center-banner.night span,
.center-banner.night strong {
  color: #ef8069;
}

.center-banner.night strong {
  text-shadow: 0 0 34px rgba(197, 52, 35, 0.55), 0 2px 22px #000;
}

.center-banner.dusk span,
.center-banner.dusk strong {
  color: #f2a266;
}

.center-banner.dawn span,
.center-banner.dawn strong {
  color: #f1d49a;
}

/* Crosshair */

.crosshair {
  position: absolute;
  top: 0;
  left: 0;

