  border-radius: 50%;
  background: rgba(7, 12, 20, 0.62);
  color: rgba(239, 228, 207, 0.78);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  transition: border-color 0.2s, color 0.2s, background 0.2s, transform 0.2s;
}

.menu-window-btn:hover,
.menu-window-btn:focus-visible {
  border-color: var(--gold);
  background: rgba(42, 33, 22, 0.86);
  color: var(--gold);
  transform: translateY(-1px);
}

.menu-window-btn.close:hover,
.menu-window-btn.close:focus-visible {
