    linear-gradient(180deg, rgba(44, 14, 15, 0.9), rgba(8, 11, 17, 0.92));
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.55), inset 0 0 32px rgba(133, 32, 28, 0.16);
  transform: translateX(-50%);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
}

.boss-bar[hidden] {
  display: none;
}

.boss-head {
